/* Three trial hair assets, one shared atlas set. No identity or save fields. */
(function(root){'use strict';const templates=new Map(),pending=new Map(),live=new Set(),pool=new Map();let created=0,released=0;
const valid=k=>['a','b','c'].includes(k),category=slot=>['aoMap','roughnessMap','metalnessMap'].includes(slot)?'orm':slot;
function load(key){if(!valid(key))return Promise.reject(Error('PORTRAIT_HAIR_UNKNOWN'));if(pending.has(key))return pending.get(key);const promise=new Promise((resolve,reject)=>{new root.CozyGLTFLoader().load('assets/portrait-hair/'+key+'.glb',gltf=>{const redundant=new Set();gltf.scene.traverse(n=>{if(!n.isMesh)return;n.castShadow=true;n.receiveShadow=false;for(const m of(Array.isArray(n.material)?n.material:[n.material]))for(const slot of['map','normalMap','aoMap','roughnessMap','metalnessMap']){const t=m[slot];if(!t)continue;const id=category(slot)+':'+t.channel+':'+t.colorSpace+':'+t.flipY;if(pool.has(id)&&pool.get(id)!==t){redundant.add(t);m[slot]=pool.get(id);}else pool.set(id,t);}});const images=new Set();for(const t of redundant){if([...pool.values()].includes(t))continue;t.dispose();if(t.image)images.add(t.image);}for(const image of images)if(![...pool.values()].some(t=>t.image===image))image.close?.();templates.set(key,gltf.scene);resolve(stats());},undefined,e=>{pending.delete(key);reject(Error(e?.message||'PORTRAIT_HAIR_LOAD_FAILED'));});});pending.set(key,promise);return promise;}
function create(key,tone){const source=templates.get(key);if(!source)return null;const group=source.clone(true),materials=new Map();group.name='portrait-hair-'+key;group.userData.portraitHair=true;group.traverse(n=>{if(n.isMesh){const tint=m=>{if(!materials.has(m)){const copy=m.clone();copy.color.setHex(tone);materials.set(m,copy);}return materials.get(m);};n.material=Array.isArray(n.material)?n.material.map(tint):tint(n.material);}});live.add(group);created++;return group;}
function release(group){if(!live.delete(group))return;const materials=new Set();group.traverse(n=>{if(n.isMesh)for(const m of(Array.isArray(n.material)?n.material:[n.material]))materials.add(m);});materials.forEach(m=>m.dispose());group.removeFromParent();released++;}
function dispose(){for(const g of [...live])release(g);const gs=new Set(),ms=new Set(),ts=new Set(pool.values());for(const t of templates.values())t.traverse(n=>{if(n.isMesh){gs.add(n.geometry);for(const m of(Array.isArray(n.material)?n.material:[n.material]))ms.add(m);}});gs.forEach(g=>g.dispose());ms.forEach(m=>m.dispose());const images=new Set();ts.forEach(t=>{t.dispose();if(t.image)images.add(t.image);});images.forEach(i=>i.close?.());templates.clear();pending.clear();pool.clear();}
function stats(){return{ready:[...templates.keys()],sharedTextures:new Set(pool.values()).size,liveInstances:live.size,created,released};}
root.CozyPortraitHair=Object.freeze({load,ready:k=>templates.has(k),create,release,dispose,stats});root.addEventListener?.('pagehide',dispose,{once:true});
})(globalThis);
